 each('[data-question]',b=>b.onclick=()=>{const r=S.redAct(data.red,'question',b.dataset.question);tell(r.message||'ลูกค้าตอบแล้ว');persist();render();});each('[data-red]',b=>b.onclick=()=>{if(isTraining()){tell('อ่านขอบเขตให้เข้าใจก่อน บทฝึกนี้ยังไม่รับงานจริง');render();return;}const action=b.dataset.red,r=S.redAct(data.red,action);tell(r.message||'บันทึกแล้ว',!r.ok);if(r.ok&&action==='accept')page='scope';if(r.ok&&action==='scope')page='pentest';persist();render();});if(one('#invoice-id'))one('#invoice-id').onchange=e=>{requestId=e.target.value;requestResult=null;render();};if(one('[data-request]'))one('[data-request]').onclick=()=>{requestResult=S.redAct(data.red,'request',requestId);tell(requestResult.message,!requestResult.ok);persist();render();};
